python3 << 'EOF'
import json
import subprocess
import sys

tests = [
    # Test 1: Basic sub-pipeline with parameters
    {
        "name": "Basic call with parameters",
        "input": {
            "defs": {
                "Normalize": { "steps":[
                    {"op":"map","as":"z","expr":"(value - params.mean) / params.std"}
                ]},
                "KeepCols": { "steps":[
                    {"op":"select","columns":["id","z"]}
                ]}
            },
            "pipeline": {
                "steps": [
                    {"op":"call","name":"Normalize","params":{"mean":100,"std":20}},
                    {"op":"call","name":"KeepCols","params":{}}
                ]
            },
            "dataset":[
                {"id":1,"value":120},
                {"id":2,"value":80}
            ]
        },
        "expected": {"rows_in": 2, "rows_out": 2}
    },

    # Test 2: Backward compatibility - operations without defs
    {
        "name": "Backward compatibility - map and filter",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"map","as":"x2","expr":"value * 2"},
                    {"op":"filter","where":"x2 > 50"}
                ]
            },
            "dataset":[
                {"id":1,"value":10},
                {"id":2,"value":40}
            ]
        },
        "expected": {"rows_in": 2, "rows_out": 1}
    },

    # Test 3: Backward compatibility - select
    {
        "name": "Backward compatibility - select",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"select","columns":["id"]}
                ]
            },
            "dataset":[
                {"id":1,"value":10},
                {"id":2,"value":40}
            ]
        },
        "expected": {"rows_in": 2, "rows_out": 2}
    },

    # Test 4: Backward compatibility - rename
    {
        "name": "Backward compatibility - rename",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"rename","from":"value","to":"val"}
                ]
            },
            "dataset":[
                {"id":1,"value":10}
            ]
        },
        "expected": {"rows_in": 1, "rows_out": 1}
    },

    # Test 5: Backward compatibility - limit
    {
        "name": "Backward compatibility - limit",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"limit","n":1}
                ]
            },
            "dataset":[
                {"id":1},
                {"id":2},
                {"id":3}
            ]
        },
        "expected": {"rows_in": 3, "rows_out": 1}
    },

    # Test 6: Backward compatibility - branch
    {
        "name": "Backward compatibility - branch",
        "input": {
            "pipeline": {
                "steps": [
                    {"op":"branch","branches":[
                        {"when":"value > 15","steps":[{"op":"map","as":"cat","expr":"'big'"}]},
                        {"when":"otherwise","steps":[{"op":"map","as":"cat","expr":"'small'"}]}
                    ]}
                ]
            },
            "dataset":[
                {"id":1,"value":10},
                {"id":2,"value":20}
            ]
        },
        "expected": {"rows_in": 2, "rows_out": 2}
    },

    # Test 7: Params in different contexts
    {
        "name": "Params in filter and branch",
        "input": {
            "defs": {
                "Categorize": {
                    "steps": [
                        {"op":"filter","where":"value >= params.threshold"},
                        {"op":"branch","branches":[
                            {"when":"value >= params.high","steps":[{"op":"map","as":"cat","expr":"'high'"}]},
                            {"when":"otherwise","steps":[{"op":"map","as":"cat","expr":"'med'"}]}
                        ]}
                    ]
                }
            },
            "pipeline": {
                "steps": [
                    {"op":"call","name":"Categorize","params":{"threshold":50,"high":100}}
                ]
            },
            "dataset":[
                {"id":1,"value":30},
                {"id":2,"value":75},
                {"id":3,"value":120}
            ]
        },
        "expected": {"rows_in": 3, "rows_out": 2}
    }
]

passed = 0
failed = 0

for test in tests:
    proc = subprocess.run(
        ['python', 'etl_pipeline.py', '--execute'],
        input=json.dumps(test["input"]),
        text=True,
        capture_output=True
    )

    if proc.returncode != 0:
        print(f"✗ {test['name']}: {proc.stderr}")
        failed += 1
        continue

    result = json.loads(proc.stdout)
    if result.get('status') != 'ok':
        print(f"✗ {test['name']}: {result}")
        failed += 1
        continue

    metrics = result['metrics']
    expected = test['expected']

    if metrics['rows_in'] == expected['rows_in'] and metrics['rows_out'] == expected['rows_out']:
        print(f"✓ {test['name']}")
        passed += 1
    else:
        print(f"✗ {test['name']}: expected {expected}, got {metrics}")
        failed += 1

print(f"\n{passed} passed, {failed} failed")
sys.exit(0 if failed == 0 else 1)
EOF

