import json
import subprocess

# Complex test: multiple nested calls with different parameters
test_input = {
    "defs": {
        "ScaleBy": {
            "steps": [
                {"op": "map", "as": "scaled", "expr": "value * params.factor"}
            ]
        },
        "FilterRange": {
            "steps": [
                {"op": "filter", "where": "scaled >= params.min"},
                {"op": "filter", "where": "scaled <= params.max"}
            ]
        },
        "ProcessData": {
            "steps": [
                {"op": "call", "name": "ScaleBy", "params": {"factor": 2}},
                {"op": "call", "name": "FilterRange", "params": {"min": 50, "max": 200}}
            ]
        }
    },
    "pipeline": {
        "steps": [
            {"op": "call", "name": "ProcessData", "params": {}},
            {"op": "select", "columns": ["id", "value", "scaled"]}
        ]
    },
    "dataset": [
        {"id": 1, "value": 10},
        {"id": 2, "value": 30},
        {"id": 3, "value": 60},
        {"id": 4, "value": 200}
    ]
}

proc = subprocess.run(
    ['python', 'etl_pipeline.py', '--execute'],
    input=json.dumps(test_input),
    text=True,
    capture_output=True
)

result = json.loads(proc.stdout)

if result.get('status') == 'ok':
    data = result['data']
    print(f"✓ Complex multi-level call works")
    print(f"  Input rows: {result['metrics']['rows_in']}")
    print(f"  Output rows: {result['metrics']['rows_out']}")
    for row in data:
        print(f"    {row}")

    # Verify correctness
    # id:1 value:10 -> scaled:20 (filtered out, < 50)
    # id:2 value:30 -> scaled:60 (passes, 50 <= 60 <= 200)
    # id:3 value:60 -> scaled:120 (passes, 50 <= 120 <= 200)
    # id:4 value:200 -> scaled:400 (filtered out, > 200)

    expected_ids = {2, 3}
    actual_ids = {row['id'] for row in data}
    if actual_ids == expected_ids:
        print(f"✓ Output data is correct (IDs {actual_ids})")
    else:
        print(f"✗ Expected IDs {expected_ids}, got {actual_ids}")
else:
    print(f"✗ Error: {result}")
EOF
